#include <vector>
#include <algorithm>

class Solution {
public:
    long long largestSquareArea(std::vector<std::vector<int>>& bottomLeft, std::vector<std::vector<int>>& topRight) {
        long long ans = 0;
        int n = bottomLeft.size();
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int w = std::min(topRight[i][0], topRight[j][0]) - std::max(bottomLeft[i][0], bottomLeft[j][0]);
                int h = std::min(topRight[i][1], topRight[j][1]) - std::max(bottomLeft[i][1], bottomLeft[j][1]);
                int e = std::min(w, h);
                if (e > 0) ans = std::max(ans, 1LL * e * e);
            }
        }
        return ans;
    }
};

class Solution {
    public long largestSquareArea(int[][] bottomLeft, int[][] topRight) {
        long ans = 0;
        int n = bottomLeft.length;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                int w = Math.min(topRight[i][0], topRight[j][0]) - Math.max(bottomLeft[i][0], bottomLeft[j][0]);
                int h = Math.min(topRight[i][1], topRight[j][1]) - Math.max(bottomLeft[i][1], bottomLeft[j][1]);
                int e = Math.min(w, h);
                if (e > 0) ans = Math.max(ans, 1L * e * e);
            }
        }
        return ans;
    }
}

var largestSquareArea = function(bottomLeft, topRight) {
    let ans = 0;
    const n = bottomLeft.length;
    for (let i = 0; i < n; ++i) {
        for (let j = i + 1; j < n; ++j) {
            const w = Math.min(topRight[i][0], topRight[j][0]) - Math.max(bottomLeft[i][0], bottomLeft[j][0]);
            const h = Math.min(topRight[i][1], topRight[j][1]) - Math.max(bottomLeft[i][1], bottomLeft[j][1]);
            const e = Math.min(w, h);
            if (e > 0) ans = Math.max(ans, e * e);
        }
    }
    return ans;
};
